using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve it.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change 2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|<key>", so preserve the legacy format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .HasJsonPropertyName("id")
                  .ToJsonProperty("id");

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // HasIndex() now throws at model validation time in EF 9.
            // Removed: entity.HasIndex(b => b.Name);
            // Create indexes directly via Cosmos DB portal/IaC instead.
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Breaking change 4: EF 9 uses PATCH (partial update) by default instead of
        // full document replace. To keep the old behavior for sync jobs that do
        // read-modify-write on full documents, opt back into replace mode.
        configurationBuilder.Conventions.Remove(
            typeof(Microsoft.EntityFrameworkCore.Cosmos.Conventions.CosmosPatchUpdateConvention));
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

