using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: id no longer includes the discriminator value.
            // Existing documents have id = "Blog|<key>", so keep the old format.
            entity.HasDiscriminatorInJsonId();

            // Breaking change 3: HasIndex() now throws instead of being silently ignored.
            // Removed: entity.HasIndex(b => b.Name);
            // Manage indexes via the Azure Cosmos DB portal or IaC instead.
        });
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

